  "interactions": [
    {
      "id": "panel",
      "type": "toggle",
      "label": "Curve",
      "options": ["(a) smooth curve", "(b) circle"],
      "default": "(a) smooth curve",
      "teaches": "The same limiting construction defines the tangent on any curve, and on a circle it reproduces the classical tangent that touches at exactly one point and is perpendicular to the radius."
    },
    {
      "id": "qApproach",
      "type": "slider",
      "label": "Position of Q (separation h from P)",
      "range": [0.02, 3.0, 0.02],
      "default": 2.4,
      "teaches": "As Q slides toward P the secant rotates continuously and its slope settles on a single limiting number — the tangent slope — even though the secant is never drawn at Q = P.",
      "teachesNote": "slope readout updates live"
    },
    {
      "id": "pPosition",
      "type": "slider",
      "label": "Position of P along the curve",
      "range": [-2.0, 2.0, 0.05],
      "default": -1.2,
      "teaches": "The tangent direction is a local property: moving P changes the limiting slope, so each point of the curve has its own tangent line."
    },
    {
      "id": "showTrail",
      "type": "toggle",
      "label": "Show fan of previous secants",
      "default": true,
      "teaches": "Seeing the whole family of secants at once makes the rotation toward one limiting position visible as a converging fan rather than a single line."
    }
  ],
  "demo_steps": [
    {
      "title": "A secant through P and Q",
      "narration": "Point P is fixed on the blue curve; Q sits well away from it. The pink line through both points is a secant, and its slope is just the average rate of change between P and Q.",
      "state": { "panel": "(a) smooth curve", "qApproach": 2.8, "pPosition": -1.2, "showTrail": false }
    },
    {
      "title": "Slide Q toward P",
      "narration": "Drag Q closer to P and watch the secant pivot about P. Each new position gives a new slope in the readout, and the slopes are marching toward one value.",
      "state": { "panel": "(a) smooth curve", "qApproach": 1.2, "pPosition": -1.2, "showTrail": true }
    },
    {
      "title": "The limiting position",
      "narration": "With Q almost on top of P, the secant has nearly stopped rotating: the fan of pink lines closes onto the shaded wedge and settles on the tangent line at P.",
